package main

import (
	"crypto/aes"
	"crypto/cipher"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"time"

	"github.com/gorilla/websocket"
)

var (
	encryptionKey = []byte("0123456789abcdef0123456789abcdef") // 32 bytes for AES-256
	upgrader      = websocket.Upgrader{
		CheckOrigin: func(r *http.Request) bool { return true },
	}
)

type Message struct {
	Type    string `json:"type"`
	Payload string `json:"payload"`
	Token   string `json:"token"`
}

type SessionToken struct {
	UserID    string `json:"user_id"`
	Role      string `json:"role"`
	ExpiresAt int64  `json:"expires_at"`
}

func pkcs7Unpad(data []byte) ([]byte, error) {
	if len(data) == 0 {
		return nil, fmt.Errorf("empty data")
	}
	padLen := int(data[len(data)-1])
	if padLen == 0 || padLen > aes.BlockSize {
		return nil, fmt.Errorf("invalid padding length: %d", padLen)
	}
	for i := len(data) - padLen; i < len(data); i++ {
		if data[i] != byte(padLen) {
			return nil, fmt.Errorf("invalid padding byte at position %d", i)
		}
	}
	return data[:len(data)-padLen], nil
}

func decryptToken(encryptedB64 string) (*SessionToken, error) {
	ciphertext, err := base64.StdEncoding.DecodeString(encryptedB64)
	if err != nil {
		return nil, fmt.Errorf("base64 decode failed")
	}
	if len(ciphertext) < aes.BlockSize {
		return nil, fmt.Errorf("ciphertext too short")
	}

	block, err := aes.NewCipher(encryptionKey)
	if err != nil {
		return nil, err
	}

	iv := ciphertext[:aes.BlockSize]
	ciphertext = ciphertext[aes.BlockSize:]

	if len(ciphertext)%aes.BlockSize != 0 {
		return nil, fmt.Errorf("ciphertext not block-aligned")
	}

	mode := cipher.NewCBCDecrypter(block, iv)
	mode.CryptBlocks(ciphertext, ciphertext)

	// Validate padding - returns specific error on padding failure
	plaintext, err := pkcs7Unpad(ciphertext)
	if err != nil {
		return nil, fmt.Errorf("decryption failed: padding error: %v", err)
	}

	var token SessionToken
	if err := json.Unmarshal(plaintext, &token); err != nil {
		return nil, fmt.Errorf("decryption failed: json parse error")
	}

	if token.ExpiresAt < time.Now().Unix() {
		return nil, fmt.Errorf("token expired")
	}

	return &token, nil
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	for {
		_, raw, err := conn.ReadMessage()
		if err != nil {
			break
		}

		var msg Message
		if err := json.Unmarshal(raw, &msg); err != nil {
			conn.WriteJSON(map[string]string{"error": "invalid message format"})
			continue
		}

		switch msg.Type {
		case "auth":
			token, err := decryptToken(msg.Token)
			if err != nil {
				// Error message differs based on padding vs JSON parse failure
				conn.WriteJSON(map[string]string{"error": err.Error()})
				continue
			}
			conn.WriteJSON(map[string]string{
				"status": "authenticated",
				"user":   token.UserID,
				"role":   token.Role,
			})
		case "data":
			conn.WriteJSON(map[string]string{"echo": msg.Payload})
		default:
			conn.WriteJSON(map[string]string{"error": "unknown message type"})
		}
	}
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/health", healthCheck)
	log.Println("WebSocket service starting on :8443")
	log.Fatal(http.ListenAndServe(":8443", nil))
}
